55	mod tests {
56	    use super::*;
57	    use serde_json::json;
58	
59	    #[test]
60	    fn zero_record_page_stops_even_when_offset_below_total() {
61	        // Regression for #78/#6: a mid-stream empty page with `total_path` set
62	        // and offset < total used to leave the offset unchanged and re-issue
63	        // the identical request forever. It must stop instead.
64	        let body = json!({ "total": 100 });
65	        let mut offset = 50usize;
66	        let has_next = advance(&body, &mut offset, 0, 20, Some("$.total")).unwrap();
67	        assert!(!has_next, "a zero-record page must stop pagination");
