    url: String,
    method: reqwest::Method,
    body: Option<Value>,
    encoding: BodyEncoding,
    token_path: String,
    expiry_path: Option<String>,
    expiry_ratio: f64,
    apply_as: ApplyAs,
    state: Mutex<CachedToken>,
}

