    let p2 = OAuth2RefreshProvider::from_config(&stale_seed)
        .unwrap()
        .with_store(store.clone(), "k");
    assert_eq!(p2.credential().await.unwrap(), Credential::Bearer("B1".into()));
    assert_eq!(
        store.get("k").await.unwrap().unwrap()["refresh_token"],
        "rt2"
