    )
    .unwrap();

    let records = stream.fetch_all().await.unwrap();
    assert_eq!(records.len(), 3);

    let requests = server.received_requests().await.unwrap();
    let b1: Value = serde_json::from_slice(&requests[1].body).unwrap();
    assert_eq!(b1["after"], "c1");
}

