//! Mutual-TLS client-certificate config tests for the XML source (#495).

use faucet_source_xml::{TlsClientConfig, XmlStreamConfig};

const CERT: &str = include_str!("fixtures/mtls/cert.pem");
const KEY: &str = include_str!("fixtures/mtls/key.pem");

fn cfg_with(tls: TlsClientConfig) -> XmlStreamConfig {
    XmlStreamConfig::new("https://example.test", "/x").tls(tls)
}

#[cfg(feature = "mtls")]
#[test]
fn pem_identity_builds_a_client() {
    let cfg = cfg_with(TlsClientConfig {
        client_cert: Some(CERT.to_string()),
        client_key: Some(KEY.to_string()),
        ..Default::default()
    });
    assert!(faucet_source_xml::XmlStream::try_new(cfg).is_ok());
}

#[cfg(feature = "mtls")]
#[test]
fn pkcs12_identity_builds_a_client() {
    let p12 = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/mtls/identity.p12");
    let cfg = cfg_with(TlsClientConfig {
        client_identity_pkcs12: Some(p12.to_string()),
        pkcs12_password: Some("changeit".into()),
        ..Default::default()
    });
    assert!(faucet_source_xml::XmlStream::try_new(cfg).is_ok());
}

#[cfg(feature = "mtls")]
#[test]
fn invalid_pem_is_rejected_without_leaking_key() {
    let cfg = cfg_with(TlsClientConfig {
        client_cert: Some("-----BEGIN CERTIFICATE-----\nnope\n-----END CERTIFICATE-----".into()),
        client_key: Some("SUPERSECRETKEYMATERIAL".into()),
        ..Default::default()
    });
    let err = faucet_source_xml::XmlStream::try_new(cfg)
        .map(|_| ())
        .expect_err("malformed PEM must error");
    assert!(!err.to_string().contains("SUPERSECRETKEYMATERIAL"));
}

#[cfg(not(feature = "mtls"))]
#[test]
fn tls_config_without_mtls_feature_errors() {
    let cfg = cfg_with(TlsClientConfig {
        client_cert: Some(CERT.to_string()),
        client_key: Some(KEY.to_string()),
        ..Default::default()
    });
    let err = faucet_source_xml::XmlStream::try_new(cfg)
        .map(|_| ())
        .expect_err("tls without the mtls feature must error");
    assert!(err.to_string().contains("mtls"));
}

