) -> Result<(), FaucetError> {
    let url = format!("{}/{}/_refresh", self.config.base_url, index);
    let resp = Self::apply_auth_value(self.client.post(&url), auth)
        .send()
        .await?;
    check_http_response(resp, DEFAULT_ERROR_BODY_MAX_LEN).await?;
    Ok(())
}

