1	//! OAuth1 (one-legged, HMAC-SHA256) request-signing provider (#496).
2	//!
3	//! Unlike the OAuth2 providers, OAuth1 has **no token to fetch**: every request
4	//! carries an `Authorization: OAuth …` header whose signature covers the HTTP
5	//! method, URL, and parameters (RFC 5849). This provider therefore overrides
6	//! [`AuthProvider::sign_request`] (computed fresh per request) rather than
7	//! [`AuthProvider::credential`]. The motivating target is NetSuite Token-Based
8	//! Auth (SuiteQL/REST), which uses HMAC-**SHA256** with a `realm`.
9	
10	use async_trait::async_trait;
11	use base64::Engine as _;
12	use faucet_core::{AuthProvider, Credential, FaucetError};
13	use hmac::{Hmac, Mac};
14	use percent_encoding::{AsciiSet, NON_ALPHANUMERIC, utf8_percent_encode};
15	use sha2::Sha256;
16	use std::collections::BTreeMap;
17	use std::sync::atomic::{AtomicU64, Ordering};
18	
19	type HmacSha256 = Hmac<Sha256>;
20	
21	/// RFC 3986 / 5849 unreserved set — everything **except** `A-Z a-z 0-9 - . _ ~`
22	/// is percent-encoded. Built by removing the four unreserved punctuation marks
23	/// from the "encode everything non-alphanumeric" set.
24	const OAUTH_ENCODE: &AsciiSet = &NON_ALPHANUMERIC
25	    .remove(b'-')
26	    .remove(b'.')
27	    .remove(b'_')
28	    .remove(b'~');
29	
30	fn enc(s: &str) -> String {
31	    utf8_percent_encode(s, OAUTH_ENCODE).to_string()
32	}
