35	pub struct OAuth1Provider {
36	    consumer_key: String,
37	    consumer_secret: String,
38	    token: String,
39	    token_secret: String,
40	    realm: Option<String>,
41	    /// Monotonic counter mixed into the nonce so two requests in the same second
42	    /// never collide.
43	    nonce_counter: AtomicU64,
44	}
