50	        f.debug_struct("OAuth1Provider")
51	            .field("consumer_key", &self.consumer_key)
52	            .field("consumer_secret", &"***")
53	            .field("token", &self.token)
54	            .field("token_secret", &"***")
55	            .field("realm", &self.realm)
56	            .finish()
