75	/// Entry point for a custom `faucet` binary that bundles third-party
76	/// connectors.
77	///
78	/// A custom-CLI author writes a tiny `main.rs` that builds a [`PluginRegistry`]
79	/// with their connectors registered on top of the built-ins and hands it here:
80	///
81	/// ```no_run
82	/// use faucet_cli::registry::PluginRegistry;
83	/// fn main() -> std::process::ExitCode {
84	///     faucet_cli::run_main(PluginRegistry::with_builtins())
85	/// }
86	/// ```
87	///
88	/// This installs `registry` as the process-global connector registry (so every
89	/// command — `run`, `validate`, `schema`, `list`, `preview`, `serve`, … — sees
90	/// the custom connectors), parses argv, installs the tracing subscriber, and
91	/// dispatches. The return value is the process exit code (the failed-probe /
92	/// failed-case / failed-unit count for `doctor` / `test` / `backfill`, `1` for
93	/// any other error, `0` on success). The stock `faucet` binary calls this with
94	/// `PluginRegistry::with_builtins()`.
95	pub fn run_main(registry: PluginRegistry) -> std::process::ExitCode {
96	    use clap::Parser;
97	    use std::process::ExitCode;
98	
99	    if let Err(err) = registry.install() {
100	        commands::report(&err);
101	        return ExitCode::from(1);
102	    }
103	
104	    // Hand `faucet-core` the secret scrubber before anything can produce output.
105	    // Core builds two things that leave the process and that it cannot redact on
106	    // its own: the DLQ envelope's `error.message`, and error text a caller
107	    // forwards on. Installed here, at the single entry point, so every subcommand
108	    // and runtime gets it (#456 H5).
109	    faucet_core::redact::install(Box::new(|s: &str| {
110	        secrets::registry::redact(s).into_owned()
111	    }));
112	
113	    // Dynamic shell completion (#383): when the shell invokes us with the
114	    // `COMPLETE` env var set, compute and print candidates, then exit — before
115	    // any normal parsing/tracing/runtime setup. A no-op otherwise. The registry
116	    // is installed above so connector-kind candidates reflect the live binary.
117	    clap_complete::env::CompleteEnv::with_factory(<Cli as clap::CommandFactory>::command)
118	        .complete();
119	
120	    let cli = Cli::parse();
121	    #[cfg(feature = "serve")]
122	    let is_serve = matches!(cli.command, Command::Serve(_));
123	    #[cfg(not(feature = "serve"))]
124	    let is_serve = false;
125	    // A `--tui` run on a real terminal routes logs into the TUI's in-memory
126	    // ring (the stdout subscriber would corrupt the alternate screen).
127	    #[cfg(feature = "cli-tui")]
128	    let is_tui = matches!(&cli.command, Command::Run(a) if tui::is_tui_session(a.tui));
129	    #[cfg(not(feature = "cli-tui"))]
130	    let is_tui = false;
131	    // `faucet mcp` (stdio) writes JSON-RPC on stdout, so its logs must go to
132	    // stderr — never the default subscriber.
133	    #[cfg(feature = "mcp")]
134	    let is_mcp = matches!(cli.command, Command::Mcp(_));
135	    #[cfg(not(feature = "mcp"))]
136	    let is_mcp = false;
137	    // `serve` installs its own (redacting, run-scoped) subscriber; every other
138	    // command uses the plain redacting fmt subscriber.
139	    if !is_serve && !is_tui && !is_mcp {
140	        install_tracing(&cli.log_level);
141	    }
142	    #[cfg(feature = "cli-tui")]
143	    if is_tui {
144	        tui::install_tui_tracing(&cli.log_level);
145	    }
146	    #[cfg(feature = "mcp")]
147	    if is_mcp {
148	        mcp::install_stderr_tracing(&cli.log_level);
149	    }
150	
151	    let runtime = match tokio::runtime::Builder::new_multi_thread()
152	        .enable_all()
153	        .build()
154	    {
155	        Ok(rt) => rt,
156	        Err(e) => {
157	            eprintln!("error: failed to start async runtime: {e}");
158	            return ExitCode::from(1);
159	        }
160	    };
161	
162	    runtime.block_on(async move {
163	        match run_command(cli).await {
164	            Ok(()) => ExitCode::SUCCESS,
165	            // `doctor` / `test` / `backfill` already printed their report; the
166	            // exit code is the failed count (clamped to 255).
167	            Err(CliError::DoctorFailed { failed }) => ExitCode::from(failed.min(255) as u8),
168	            Err(CliError::TestsFailed { failed }) => ExitCode::from(failed.min(255) as u8),
169	            Err(CliError::BackfillFailed { failed }) => ExitCode::from(failed.min(255) as u8),
170	            Err(err) => {
171	                commands::report(&err);
172	                ExitCode::from(1)
173	            }
174	        }
175	    })
176	}
