3	use crate::config::{FileFormat, HttpFileAuth, HttpFileSourceConfig};
4	use async_trait::async_trait;
5	use faucet_core::{Credential, FaucetError, SharedAuthProvider, Source, Stream, StreamPage};
6	use reqwest::{Client, RequestBuilder};
7	use serde_json::{Map, Value};
8	use std::collections::HashMap;
9	use std::pin::Pin;
10	use std::time::Duration;
11	
12	/// A source that downloads a file from an authenticated HTTP/Graph URL and
13	/// parses it (CSV always; Excel behind the `excel` feature) into records.
14	pub struct HttpFileSource {
15	    config: HttpFileSourceConfig,
16	    client: Client,
17	    /// Optional shared auth provider (from `auth: { ref }` or a library caller).
18	    /// Takes precedence over inline auth.
19	    auth_provider: Option<SharedAuthProvider>,
20	}
21	
22	impl HttpFileSource {
23	    /// Create a new source from the given config.
24	    pub fn new(config: HttpFileSourceConfig) -> Result<Self, FaucetError> {
25	        config.validate()?;
26	        let mut builder = Client::builder();
27	        if let Some(secs) = config.timeout_secs {
28	            builder = builder.timeout(Duration::from_secs(secs));
29	        } else {
30	            builder = builder.timeout(Duration::from_secs(60));
31	        }
32	        let client = builder
33	            .build()
34	            .map_err(|e| FaucetError::Config(format!("http-file: build HTTP client: {e}")))?;
35	        Ok(Self {
36	            config,
37	            client,
38	            auth_provider: None,
39	        })
40	    }
41	
42	    /// Attach a shared [`AuthProvider`](faucet_core::AuthProvider) (resolved from
43	    /// `auth: { ref }` by the CLI, or injected by a library caller). Takes
44	    /// precedence over inline auth.
45	    pub fn with_auth_provider(mut self, provider: SharedAuthProvider) -> Self {
46	        self.auth_provider = Some(provider);
47	        self
48	    }
49	
50	    /// Download the file bytes, applying auth.
51	    async fn fetch_bytes(&self, url: &str) -> Result<Vec<u8>, FaucetError> {
52	        let mut req = self.client.get(url);
53	        req = if let Some(provider) = &self.auth_provider {
54	            apply_credential(req, provider.credential().await?)
55	        } else {
56	            match self.config.auth.inline() {
57	                Some(auth) => apply_inline_auth(req, auth),
58	                None => req, // a `{ ref }` with no provider wired — send unauth'd
59	            }
60	        };
61	        let resp = req
62	            .send()
63	            .await
64	            .map_err(|e| FaucetError::Source(format!("http-file: request to {url} failed: {e}")))?;
65	        let status = resp.status();
66	        if !status.is_success() {
67	            let body = resp.text().await.unwrap_or_default();
68	            let body = body.chars().take(512).collect::<String>();
69	            return Err(FaucetError::HttpStatus {
70	                status: status.as_u16(),
71	                url: url.to_string(),
72	                body,
73	            });
74	        }
75	        Ok(resp
76	            .bytes()
77	            .await
78	            .map_err(|e| FaucetError::Source(format!("http-file: reading body of {url}: {e}")))?
79	            .to_vec())
80	    }
81	
82	    /// Parse downloaded bytes into records per the resolved format.
83	    async fn parse(&self, bytes: &[u8]) -> Result<Vec<Value>, FaucetError> {
84	        match self.config.resolved_format() {
85	            FileFormat::Csv | FileFormat::Auto => {
86	                parse_csv(bytes, self.config.delimiter, self.config.has_headers).await
87	            }
88	            FileFormat::Excel => {
89	                parse_excel(bytes, self.config.sheet.as_deref(), self.config.header_row)
90	            }
91	        }
92	    }
93	}
94	
95	/// Apply an inline [`HttpFileAuth`] to the request.
96	fn apply_inline_auth(req: RequestBuilder, auth: &HttpFileAuth) -> RequestBuilder {
97	    match auth {
98	        HttpFileAuth::None => req,
99	        HttpFileAuth::Bearer { token } => req.bearer_auth(token),
100	        HttpFileAuth::Basic { username, password } => req.basic_auth(username, Some(password)),
101	        HttpFileAuth::ApiKey { header, value } => req.header(header, value),
102	        HttpFileAuth::Custom { headers } => {
103	            let mut req = req;
104	            for (k, v) in headers {
105	                req = req.header(k, v);
106	            }
107	            req
108	        }
109	    }
110	}
111	
112	/// Apply a shared-provider [`Credential`] to the request.
113	fn apply_credential(req: RequestBuilder, cred: Credential) -> RequestBuilder {
114	    match cred {
115	        Credential::Bearer(token) => req.bearer_auth(token),
116	        Credential::Token(token) => req.header(reqwest::header::AUTHORIZATION, token),
117	        Credential::Basic { username, password } => req.basic_auth(username, Some(password)),
118	        Credential::Header { name, value } => req.header(name, value),
119	    }
120	}
