122	/// Parse CSV bytes into records. Header row (when `has_headers`) supplies field
123	/// names; otherwise fields are named `column_N`. Values are strings (like the
124	/// `csv` source). Pure (no network).
125	pub async fn parse_csv(
126	    bytes: &[u8],
127	    delimiter: u8,
128	    has_headers: bool,
129	) -> Result<Vec<Value>, FaucetError> {
130	    use futures::StreamExt as _;
131	    let mut rdr = csv_async::AsyncReaderBuilder::new()
132	        .has_headers(false)
133	        .delimiter(delimiter)
134	        .flexible(true)
135	        .create_reader(bytes);
136	    let mut records = rdr.records();
137	    let mut headers: Option<Vec<String>> = None;
138	    let mut out = Vec::new();
139	    while let Some(rec) = records.next().await {
140	        let rec =
141	            rec.map_err(|e| FaucetError::Source(format!("http-file: CSV parse error: {e}")))?;
142	        if has_headers && headers.is_none() {
143	            headers = Some(rec.iter().map(str::to_string).collect());
144	            continue;
145	        }
146	        let mut obj = Map::new();
147	        for (i, field) in rec.iter().enumerate() {
148	            let key = headers
149	                .as_ref()
150	                .and_then(|h| h.get(i).cloned())
151	                .unwrap_or_else(|| format!("column_{i}"));
152	            obj.insert(key, Value::String(field.to_string()));
153	        }
154	        out.push(Value::Object(obj));
155	    }
156	    Ok(out)
157	}
