    cfg.batch_size = 1;
    let source = HttpFileSource::new(cfg).unwrap();

    let ctx = HashMap::new();
    let mut s = source.stream_pages(&ctx, 1);
    let mut pages = 0;
    let mut total = 0;
    while let Some(page) = s.next().await {
        let page = page.unwrap();
