1	//! Pure planning logic for the discovery-driven request matrix (#501).
2	//!
3	//! A `discover:` row enumerates a value-set at runtime (build source → drain →
4	//! project `select` → dedup); a `for_each: [dims]` row fans out over the
5	//! **cartesian product** of those value-sets, one invocation per tuple.
6	//!
7	//! Everything here is pure (no I/O): projection, dedup, the cartesian product,
8	//! the per-tuple interpolation context, and the tuple state-key suffix — so the
9	//! fan-out semantics are unit-testable without a network. The only I/O (running
10	//! the discovery source) lives in the executor and feeds [`Dim::values`].
11	
12	use serde_json::{Map, Value};
13	use std::collections::HashMap;
14	
15	/// Hard ceiling on the number of invocations a single `for_each` row may expand
16	/// to. A cartesian product multiplies quickly; above this the run fails rather
17	/// than silently spawning an unbounded fleet.
18	pub const MAX_MATRIX_PRODUCT: usize = 10_000;
19	
20	/// One resolved discovery dimension: the discovery row id, the alias its
21	/// projected value is exposed under, and the deduped value-set.
22	#[derive(Debug, Clone, PartialEq)]
23	pub struct Dim {
24	    /// Discovery row id (the `${<id>.<alias>}` reference target).
25	    pub id: String,
26	    /// Alias the projected value is exposed under.
27	    pub alias: String,
28	    /// Projected, deduped values (first-seen order).
29	    pub values: Vec<Value>,
30	}
31	
32	/// Project `select` (a dot-path, optionally `$`-prefixed) from each record and
33	/// dedup the results in first-seen order. `null` / missing projections are
34	/// skipped. `$` (or `""`) selects the whole record. Pure.
35	pub fn project_dedup(records: &[Value], select: &str) -> Vec<Value> {
36	    let mut seen: Vec<Value> = Vec::new();
37	    for rec in records {
38	        let Some(v) = project_value(rec, select) else {
39	            continue;
40	        };
41	        if v.is_null() {
42	            continue;
43	        }
44	        if !seen.contains(&v) {
45	            seen.push(v);
46	        }
47	    }
48	    seen
49	}
50	
51	/// Resolve a dot-path projection against one record. Supports a leading `$.` or
52	/// bare `$` (whole record), then `a.b.c` segment walking into objects. Returns
53	/// `None` if any segment is missing. Pure.
54	fn project_value(record: &Value, select: &str) -> Option<Value> {
55	    let path = select
56	        .strip_prefix("$.")
57	        .or_else(|| select.strip_prefix('$'))
58	        .unwrap_or(select);
59	    if path.is_empty() {
60	        return Some(record.clone());
61	    }
62	    let mut cur = record;
63	    for seg in path.split('.') {
64	        cur = cur.get(seg)?;
65	    }
66	    Some(cur.clone())
67	}
68	
69	/// The number of invocations `dims` expands to (the product of the value-set
70	/// sizes). Returns `0` if any dimension is empty. Saturating, so it never
71	/// overflows; compare against [`MAX_MATRIX_PRODUCT`]. Pure.
72	pub fn product_size(dims: &[Dim]) -> usize {
73	    if dims.is_empty() {
74	        return 0;
75	    }
76	    dims.iter()
77	        .map(|d| d.values.len())
78	        .try_fold(1usize, |acc, n| acc.checked_mul(n))
79	        .unwrap_or(usize::MAX)
80	}
81	
82	/// Build the cartesian product of the dimensions as per-tuple interpolation
83	/// contexts. Each context maps `dim_id -> { alias: value }`, so a token
84	/// `${dim_id.alias}` resolves to that tuple's value via the same
85	/// `interpolate_record` path the parent/child matrix uses. An empty dimension
86	/// yields no tuples. Pure.
87	pub fn cartesian(dims: &[Dim]) -> Vec<HashMap<String, Value>> {
88	    if dims.is_empty() || dims.iter().any(|d| d.values.is_empty()) {
89	        return Vec::new();
90	    }
91	    let mut out: Vec<HashMap<String, Value>> = vec![HashMap::new()];
92	    for dim in dims {
93	        let mut next = Vec::with_capacity(out.len() * dim.values.len());
94	        for base in &out {
95	            for v in &dim.values {
96	                let mut ctx = base.clone();
97	                let mut obj = Map::new();
98	                obj.insert(dim.alias.clone(), v.clone());
99	                ctx.insert(dim.id.clone(), Value::Object(obj));
100	                next.push(ctx);
101	            }
102	        }
103	        out = next;
104	    }
105	    out
106	}
107	
108	/// Stable, collision-resistant state-key suffix for one product tuple, in
109	/// declared dimension order: `alias=value&alias=value…`. `dims` supplies the
110	/// order + aliases; `ctx` is one entry from [`cartesian`]. Pure.
111	pub fn tuple_state_key_suffix(dims: &[Dim], ctx: &HashMap<String, Value>) -> String {
112	    dims.iter()
113	        .map(|d| {
114	            let v = ctx
115	                .get(&d.id)
116	                .and_then(|o| o.get(&d.alias))
117	                .map(value_brief)
118	                .unwrap_or_else(|| "(missing)".to_string());
119	            format!("{}={}", d.alias, v)
120	        })
121	        .collect::<Vec<_>>()
122	        .join("&")
123	}
124	
125	/// Brief scalar rendering of a JSON value for a state-key segment.
126	fn value_brief(v: &Value) -> String {
127	    match v {
128	        Value::String(s) => s.clone(),
129	        Value::Null => "null".to_string(),
130	        other => other.to_string(),
131	    }
132	}
133	
134	#[cfg(test)]
135	mod tests {
136	    use super::*;
137	    use serde_json::json;
138	
139	    #[test]
140	    fn project_dedup_dotpath_and_dollar() {
141	        let recs = vec![
142	            json!({"id": 1, "name": "a"}),
143	            json!({"id": 2, "name": "b"}),
144	            json!({"id": 1, "name": "c"}), // dup id
145	        ];
146	        assert_eq!(project_dedup(&recs, "$.id"), vec![json!(1), json!(2)]);
147	        assert_eq!(project_dedup(&recs, "id"), vec![json!(1), json!(2)]);
148	        // `$` selects whole records (all distinct here).
149	        assert_eq!(project_dedup(&recs, "$").len(), 3);
150	    }
151	
152	    #[test]
153	    fn project_dedup_skips_null_and_missing() {
154	        let recs = vec![
155	            json!({"id": 1}),
156	            json!({"id": null}),
157	            json!({"other": 9}), // missing `id`
158	            json!({"id": 2}),
159	        ];
160	        assert_eq!(project_dedup(&recs, "$.id"), vec![json!(1), json!(2)]);
161	    }
162	
163	    #[test]
164	    fn project_nested_path() {
165	        let recs = vec![
166	            json!({"meta": {"code": "X"}}),
167	            json!({"meta": {"code": "Y"}}),
168	        ];
169	        assert_eq!(
170	            project_dedup(&recs, "$.meta.code"),
171	            vec![json!("X"), json!("Y")]
172	        );
173	    }
174	
175	    fn dim(id: &str, alias: &str, vals: Vec<Value>) -> Dim {
176	        Dim {
177	            id: id.into(),
178	            alias: alias.into(),
179	            values: vals,
180	        }
181	    }
182	
183	    #[test]
184	    fn cartesian_two_dims_is_product() {
185	        let dims = vec![
186	            dim("subs", "subsidiary_id", vec![json!(1), json!(2)]),
187	            dim(
188	                "fields",
189	                "field_id",
190	                vec![json!("a"), json!("b"), json!("c")],
191	            ),
192	        ];
193	        let ctxs = cartesian(&dims);
194	        assert_eq!(ctxs.len(), 6);
195	        // First tuple pairs the first value of each dim.
196	        assert_eq!(ctxs[0]["subs"]["subsidiary_id"], json!(1));
197	        assert_eq!(ctxs[0]["fields"]["field_id"], json!("a"));
198	        // Product covers every combination.
199	        let pairs: Vec<(Value, Value)> = ctxs
200	            .iter()
201	            .map(|c| {
202	                (
203	                    c["subs"]["subsidiary_id"].clone(),
204	                    c["fields"]["field_id"].clone(),
205	                )
206	            })
207	            .collect();
208	        assert!(pairs.contains(&(json!(2), json!("c"))));
209	    }
210	
211	    #[test]
212	    fn cartesian_single_dim() {
213	        let dims = vec![dim("d", "v", vec![json!(1), json!(2)])];
214	        let ctxs = cartesian(&dims);
215	        assert_eq!(ctxs.len(), 2);
216	        assert_eq!(ctxs[1]["d"]["v"], json!(2));

