while true; do
  s=$(gh pr checks 509 --repo faucet-hq/faucet-stream --json name,state 2>/dev/null) || { sleep 60; continue; }
  echo "$s" | jq -r '.[] | select(.name=="Coverage" and .state!="IN_PROGRESS" and .state!="QUEUED" and .state!="PENDING") | "Coverage: \(.state)"'
  echo "$s" | jq -r '.[] | select(.state=="FAILURE" or .state=="ERROR") | "\(.name): \(.state)"'
  m=$(gh pr view 509 --repo faucet-hq/faucet-stream --json state --jq .state 2>/dev/null)
  [ "$m" = "MERGED" ] && { echo "PR-MERGED"; break; }
  echo "$s" | jq -e '(length>0) and all(.state!="PENDING" and .state!="QUEUED" and .state!="IN_PROGRESS")' >/dev/null 2>&1 && { echo "ALL-CHECKS-DONE state=$m"; break; }
  sleep 90
done

