fn apply(&self, rec: Value) -> Vec<Value> {
    let s = &self.spec;
    let Value::Object(map) = &rec else {
        return vec![rec];
    };
    // id columns copied onto every output row.
    let mut id = serde_json::Map::new();
    for f in &s.id_fields {
        if let Some(v) = map.get(f) {
            id.insert(f.clone(), v.clone());
        }
    }
