162	            ("integer", "integer"),
163	            ("BIGINT", "integer"),
164	            ("smallint", "integer"),
165	            ("tinyint(1)", "integer"),
166	            ("serial", "integer"),
167	            ("double precision", "number"),
168	            ("NUMERIC(10,2)", "number"),
169	            ("decimal", "number"),
170	            ("float8", "number"),
171	            ("money", "number"),
172	            ("boolean", "boolean"),
173	            ("BOOL", "boolean"),
174	            ("bit", "boolean"),
175	            ("json", "object"),
176	            ("JSONB", "object"),
177	            ("VARIANT", "object"),
178	            ("STRUCT<a INT>", "object"),
179	            ("ARRAY", "array"),
180	            ("_int4", "array"),
181	            ("text", "string"),
182	            ("character varying", "string"),
